//! Stock Viewer: type a ticker, see its quote, a price chart, daily history, company
//! details, and links that open in the browser.
//!
//! A PeroxIDE sample. The window is `ui/main_window.slint`, made in PeroxIDE's form
//! designer; each `callback` it declares is a method of `MainWindowHandlers` below
//! (generated by `build.rs`), and the properties the designer marked "use from code"
//! have `get_`/`set_` methods. `BUILDING.md` tells how the app was built.
//!
//! - `data`: fetching from Yahoo Finance and SEC EDGAR, and parsing their JSON.
//! - `chart`: closing prices as path commands for the chart.
//! - `format`: prices, volumes, dates as text.

mod chart;
mod data;
mod format;

perox_ui::include_ui!();

use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, Mutex, PoisonError};

use slint::{ComponentHandle, ModelRc, SharedString, StandardListViewItem, VecModel};

/// What the handlers share with the background lookups.
#[derive(Debug, Default)]
struct App {
    /// The links for the stock on show (filled in by the lookup that showed it).
    links: Arc<Mutex<data::Links>>,
    /// Bumped by each lookup; a lookup that finishes after a newer one started is
    /// thrown away, so a slow answer never replaces a newer one.
    latest: Arc<AtomicU64>,
}

impl App {
    /// Looks up what's in the ticker box over the chosen range, without blocking the
    /// window: the network calls run on a thread, and the result comes back to the UI
    /// thread with `upgrade_in_event_loop`.
    fn look_up(&mut self, ui: &MainWindow) {
        let Some(ticker) = data::normalize_ticker(&ui.get_ticker_edit_text()) else {
            ui.set_status_text("Type a ticker symbol, like AAPL or MSFT.".into());
            return;
        };
        let range = ui.get_range_box_current_index().max(0) as usize;
        let id = self.latest.fetch_add(1, Ordering::SeqCst) + 1;
        ui.set_busy_visible(true);
        ui.set_status_text(format!("Looking up {ticker}…").into());

        let (window, latest, links) = (ui.as_weak(), self.latest.clone(), self.links.clone());
        std::thread::spawn(move || {
            let result = data::fetch(&ticker, range);
            if latest.load(Ordering::SeqCst) != id {
                return; // a newer lookup has started
            }
            if let Ok(found) = &result {
                *links.lock().unwrap_or_else(PoisonError::into_inner) = found.links();
            }
            let _ = window.upgrade_in_event_loop(move |ui| {
                ui.set_busy_visible(false);
                match result {
                    Ok(found) => show(&ui, &found, range),
                    Err(e) => ui.set_status_text(e.into()),
                }
            });
        });
    }

    /// Opens one of the current stock's links in the default browser.
    fn open(&self, ui: &MainWindow, pick: fn(&data::Links) -> Option<String>) {
        let url = pick(&self.links.lock().unwrap_or_else(PoisonError::into_inner));
        if let Some(url) = url
            && let Err(e) = webbrowser::open(&url)
        {
            ui.set_status_text(format!("Couldn't open the browser: {e}").into());
        }
    }
}

impl MainWindowHandlers for App {
    fn about_clicked(&mut self, ui: &MainWindow) {
        if let Ok(about) = AboutDialog::new() {
            let _ = about.exec(Some(ui.window()), |_| {});
        }
    }

    fn lookup_clicked(&mut self, ui: &MainWindow) {
        self.look_up(ui);
    }

    /// Return in the ticker box.
    fn ticker_edit_accepted(&mut self, ui: &MainWindow, _text: SharedString) {
        self.look_up(ui);
    }

    /// A new range: look the stock up again, if there is one.
    fn range_box_selected(&mut self, ui: &MainWindow, _current_value: SharedString) {
        if !ui.get_ticker_edit_text().trim().is_empty() {
            self.look_up(ui);
        }
    }

    fn yahoo_link_clicked(&mut self, ui: &MainWindow) {
        self.open(ui, |l| Some(l.yahoo.clone()).filter(|u| !u.is_empty()));
    }

    fn sec_link_clicked(&mut self, ui: &MainWindow) {
        self.open(ui, |l| l.sec.clone());
    }

    fn filing_link_clicked(&mut self, ui: &MainWindow) {
        self.open(ui, |l| l.annual_report.clone());
    }

    fn website_link_clicked(&mut self, ui: &MainWindow) {
        self.open(ui, |l| l.website.clone());
    }
}

/// Puts a lookup's result into the window.
fn show(ui: &MainWindow, d: &data::StockData, range: usize) {
    let q = &d.quote;
    let c = &d.company;
    let text = |s: String| SharedString::from(s);

    // Quote.
    ui.set_company_name_text(text(format!("{} ({})", q.name, q.symbol)));
    ui.set_price_text(text(format!("{} {}", format::money(q.price), q.currency)));
    ui.set_change_text(text(format!(
        "{} today",
        format::change(q.price, q.previous_close)
    )));
    ui.set_day_range_text(text(format!(
        "Day: {} – {}",
        format::money(q.day_low),
        format::money(q.day_high)
    )));
    ui.set_year_range_text(text(format!(
        "52 weeks: {} – {}",
        format::money(q.year_low),
        format::money(q.year_high)
    )));
    ui.set_volume_text(text(format!("Volume: {}", format::volume(q.volume))));

    // Company: one line per fact a source gave, so nothing shows as a blank label.
    let mut facts: Vec<String> = Vec::new();
    let mut fact = |label: &str, value: &str| {
        if !value.is_empty() {
            facts.push(format!("{label}: {value}"));
        }
    };
    let sector = [c.sector.as_str(), c.industry.as_str()]
        .into_iter()
        .filter(|s| !s.is_empty())
        .collect::<Vec<_>>()
        .join(" · ");
    fact("Sector", &sector);
    fact("Exchange", &q.exchange);
    fact("Address", &c.address);
    fact("Incorporated in", &c.incorporated);
    fact("Fiscal year ends", &format::month_day(&c.fiscal_year_end));
    facts.push(match (&c.cik, &c.annual_report) {
        (cik, Some(r)) if !cik.is_empty() => {
            format!("SEC CIK {cik} · last {} filed {}", r.form, r.date)
        }
        (cik, None) if !cik.is_empty() => format!("SEC CIK {cik}"),
        _ => "Not an SEC filer, so there are no company filings to show.".into(),
    });
    ui.set_company_details_text(text(facts.join("\n")));

    // Chart and history (newest first in the table).
    let closes: Vec<f64> = d.bars.iter().map(|b| b.close).collect();
    ui.set_chart_line_commands(chart::line_commands(&closes).into());
    let rows: Vec<ModelRc<StandardListViewItem>> = d
        .bars
        .iter()
        .rev()
        .map(|b| {
            let cells: Vec<StandardListViewItem> = [
                format::date(b.time),
                format::money(b.open),
                format::money(b.high),
                format::money(b.low),
                format::money(b.close),
                format::volume(b.volume),
            ]
            .into_iter()
            .map(|s| StandardListViewItem::from(SharedString::from(s)))
            .collect();
            ModelRc::new(VecModel::from(cells))
        })
        .collect();
    ui.set_history_table_rows(ModelRc::new(VecModel::from(rows)));

    // Links: each button only when there's somewhere to go.
    let links = d.links();
    ui.set_yahoo_link_enabled(true);
    ui.set_sec_link_enabled(links.sec.is_some());
    ui.set_filing_link_enabled(links.annual_report.is_some());
    ui.set_website_link_enabled(links.website.is_some());

    let (label, _, _) = data::RANGES[range.min(data::RANGES.len() - 1)];
    ui.set_status_text(text(format!(
        "{} · {label} · {} prices · Yahoo Finance and SEC EDGAR",
        q.symbol,
        d.bars.len()
    )));
}

/// Starts the window. `stock-viewer TICKER` looks the ticker up straight away.
fn main() -> Result<(), slint::PlatformError> {
    let ui = MainWindow::new()?;
    let mut app = App::default();
    if let Some(ticker) = std::env::args().nth(1) {
        ui.set_ticker_edit_text(ticker.into());
        app.look_up(&ui);
    }
    ui.connect(app);
    ui.run()
}
